using Commerce;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace ShoppingCart.Tests;

[TestClass]
public class ShoppingCartTests
{
    private Commerce.ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new Commerce.ShoppingCart();

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);
        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-001", 5.00m, 3);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsCorrectly()
    {
        _cart.AddItem("SKU-001", 10.00m, 2);
        _cart.AddItem("SKU-002", 7.50m, 1);
        Assert.AreEqual(27.50m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothCounted()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 2);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_ExcludedFromTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 5.00m, 1);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(5.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NO-SUCH"));
    }

    [TestMethod]
    public void RemoveItem_RemovesDuplicateSkus()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 2);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- GetTotal Tests ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterRemovingAllItems_ReturnsZero()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- ApplyPromoCode Tests ---

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_Save10_Applies10PercentDiscount()
    {
        _cart.AddItem("SKU-001", 100.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        Assert.AreEqual(90.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_Save20_Applies20PercentDiscount()
    {
        _cart.AddItem("SKU-001", 50.00m, 2);
        _cart.ApplyPromoCode("SAVE20");
        Assert.AreEqual(80.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_Half_Applies50PercentDiscount()
    {
        _cart.AddItem("SKU-001", 40.00m, 1);
        _cart.ApplyPromoCode("HALF");
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_NoDiscount()
    {
        _cart.AddItem("SKU-001", 100.00m, 1);
        _cart.ApplyPromoCode("INVALID");
        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_SecondCodeOverridesFirst()
    {
        _cart.AddItem("SKU-001", 100.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        _cart.ApplyPromoCode("SAVE20");
        Assert.AreEqual(80.00m, _cart.GetTotal());
    }
}

